/**
 * Morph — a compiler-driven UI framework for building native desktop apps
 * with JSX and TypeScript.
 *
 * This module is the public API surface for the Morph runtime. The runtime
 * ships as a small placeholder here because all Morph code — including
 * `CSS.load`, `morphState`, and `morphEffect` — is compiled into native
 * code at build time by the Morph compiler.
 *
 * @module morph
 * @packageDocumentation
 */

/** A CSS module. Importing one is a no-op at runtime; styles are inlined at build time. */
declare module "*.css"

/** Dispatches a state update, returning `undefined` when complete. */
type DispatchEffect<A> = (value: A) => void;

/** A state value, or an updater function that receives the previous state. */
type SetStateAction<S> = S | ((prevState: S) => S);

/** Global JSX namespace used by `.mx` / `.tsx` source files. */
declare namespace JSX {
  interface IntrinsicElements {
    [elemName: string]: any
  }
}

/**
 * Describes the native application window.
 *
 * May be supplied either in `morph.config.json` (under the `window` key) or
 * by exporting a `windowConfig` object from your entry file.
 *
 * @example
 * export const windowConfig = {
 *   title: "Morph Installer",
 *   width: 700,
 *   height: 520,
 * }
 */
export interface WindowConfig {
  /** The window title shown in the title bar. */
  title: string
  /** The window width in CSS pixels. */
  width: number
  /** The window height in CSS pixels. */
  height: number
  /** Minimum window width (optional). */
  minWidth?: number
  /** Minimum window height (optional). */
  minHeight?: number
  /** Maximum window width (optional). */
  maxWidth?: number
  /** Maximum window height (optional). */
  maxHeight?: number
}

/**
 * Build-time CSS loading API.
 *
 * `CSS.load()` calls are intercepted by the Morph compiler and replaced with
 * the actual style-injection code at build time. This class exists at runtime
 * only so that tooling (Node, bundlers, TypeScript) can resolve the import.
 */
export declare class CSS {
  /**
   * Loads a stylesheet into the application.
   *
   * @param path - A local file path (e.g. `"./style.css"`) or an absolute URL
   *               (e.g. `"https://example.com/style.css"`).
   *
   * @example
   * import { CSS } from "morph";
   * CSS.load("./style.css");
   * CSS.load("https://cdn.example.com/theme.css");
   */
  static load(path: string): void
}

/**
 * Creates a reactive state variable.
 *
 * Returns a tuple of the current state and a dispatcher used to update it.
 * The dispatcher accepts either a new value or an updater function, mirroring
 * React's `useState`. Morph tracks the variable and automatically re-renders
 * the component whenever its value changes.
 *
 * @typeParam S - The type of the state value.
 * @param initialState - The initial state value.
 * @returns A tuple `[state, setState]` where `setState` accepts a new value or
 *          an updater function.
 *
 * @example
 * import { morphState } from "morph";
 *
 * const [count, setCount] = morphState(0);
 * setCount(count + 1);      // direct value
 * setCount((prev) => prev + 1); // updater function
 */
export declare function morphState<S>(initialState: S): [S, DispatchEffect<SetStateAction<S>>];

/**
 * Registers a side-effect to run after the component renders.
 *
 * The effect runs once after the initial render, and again whenever any value
 * in `deps` changes. An optional cleanup function is invoked before the effect
 * re-runs and when the component unmounts.
 *
 * @param effect - The side-effect to run. May return a cleanup function.
 * @param deps   - (Optional) Dependency list. The effect re-runs only when one
 *                 of these values changes. Omit to run after every render.
 * @returns `void`
 *
 * @example
 * import { morphState, morphEffect } from "morph";
 *
 * const [count, setCount] = morphState(0);
 * morphEffect(() => {
 *   console.log(`Count changed to: ${count}`);
 * }, [count]);
 */
export declare function morphEffect(effect: () => void | (() => void), deps?: readonly any[]): void;
